-- 인급동 / 박제 / 장항준적 사고 추가 (479-481, 2026-09-13 아침 검수 승인 — slang_candidates draft_payload 그대로).
-- 인급동: [표준사전: 없음] 유튜브 '인기 급상승 동영상' 줄임말. 출처 캐릿·아하·짤방 밈사전·슬랭존.
--   줄임말이 굳은 시점을 밝힌 출처가 없어 시기는 적지 않았다.
-- 박제: [표준사전: 뜻다름] 사전에는 동물 표본 뜻만 있음. 출처 나무위키·위키백과 신조어 목록·인스타공백·슬랭존.
--   '2018년경 등장'은 출처 한 곳뿐이라 origin에서 시기·발원지를 확정하지 않았다. secondary는 frequently-used.
-- 장항준적 사고: [표준사전: 없음] 원영적 사고(447)의 '○○적 사고' 틀을 빌린 2026년 파생어.
--   출처 위픽레터·오브루이스. 계기가 된 인터뷰·발언은 특정되지 않아 origin에 넣지 않았다.
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.

insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations) values
('479', '인급동', 'In-geup-dong', 'reels', null, '''인기 급상승 동영상'' — 지금 유튜브에서 제일 터진 영상', '{"de": "Kurz für YouTubes Trending-Videos — was gerade durch die Decke geht", "en": "Short for YouTube''s trending videos — what''s blowing up right now", "es": "Abreviatura de ''vídeos en tendencia'' de YouTube — lo que explota ahora", "ja": "「人気急上昇動画」の略 — 今いちばんバズっている動画", "vi": "Viết tắt của ''video thịnh hành'' trên YouTube — thứ đang bùng nổ"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Das Video war gestern angeblich die Nummer 1 in den Trends.", "es": "Dicen que este vídeo fue el número 1 en tendencias ayer.", "ja": "この動画、昨日の急上昇1位だったって。", "vi": "Nghe nói video này hôm qua đứng nhất thịnh hành.", "eng": "Apparently this video was #1 on trending yesterday.", "kor": "이 영상 어제 인급동 1위였대."}, {"de": "Wenn unser Short auch nur einmal in die Trends käme, hätte ich nichts mehr zu wünschen.", "es": "Si nuestro Short llegara a tendencias una sola vez, no pediría más.", "ja": "うちのショート、一回でも急上昇入ったら思い残すことない。", "vi": "Shorts của tụi mình mà lên thịnh hành một lần thôi là mãn nguyện.", "eng": "If our Shorts hit trending just once, I''d have nothing left to wish for.", "kor": "우리 쇼츠 인급동 한 번만 가면 소원이 없겠다."}], "definition": "유튜브 한국어 화면의 ''인기 급상승 동영상''을 네 글자로 줄인 말. 좁게는 조회수가 오르는 속도와 화제성을 유튜브가 종합해 뽑는 공식 순위를 가리키고, 넓게는 ''지금 제일 화제인 영상''이라는 뜻으로 쓴다. 그래서 유튜브 밖 틱톡·릴스에서 터진 영상에도 비유로 갖다 붙인다.", "definition_i18n": {"de": "Eine viersilbige Kurzform von 인기 급상승 동영상, dem koreanischen Namen für YouTubes Trending-Tab. Eng gefasst meint es dieses offizielle Ranking, das YouTube aus Aufrufgeschwindigkeit und Gesprächswert bildet. Weit gefasst heißt es einfach ''das Video, das gerade alle schauen'', also auch TikTok- und Reels-Hits.", "en": "A four-syllable clipping of 인기 급상승 동영상, the Korean name for YouTube''s Trending tab. Narrowly it means that official ranking, which YouTube builds from how fast views are climbing plus how much buzz a clip has. Loosely it just means ''the video everyone is watching right now'', so people use it for TikTok and Reels hits too.", "es": "Recorte de cuatro sílabas de 인기 급상승 동영상, el nombre coreano de la pestaña Tendencias de YouTube. En sentido estricto es ese ranking oficial, que YouTube arma según la velocidad de subida de visitas y el revuelo. En sentido amplio significa ''el vídeo que todos ven ahora'', y se aplica también a éxitos de TikTok o Reels.", "ja": "YouTube韓国語版の「人気急上昇動画」を4文字に縮めた語。狭くは再生数の伸びと話題性からYouTubeが選ぶ公式ランキングを指し、広くは「今いちばん話題の動画」という意味で使う。そのためTikTokやリールでバズった動画にも比喩的に使われる。", "vi": "Dạng rút gọn bốn âm tiết của 인기 급상승 동영상, tên tiếng Hàn của mục Thịnh hành trên YouTube. Nghĩa hẹp là bảng xếp hạng chính thức đó, do YouTube chọn dựa trên tốc độ tăng lượt xem và độ bàn tán. Nghĩa rộng chỉ ''video ai cũng đang xem'', nên cũng dùng cho clip hot trên TikTok hay Reels."}}]'::jsonb, '유튜브 한국어 화면의 메뉴 이름 ''인기 급상승 동영상''에서 앞 글자만 따 온 줄임말이다. 유튜브 쪽 설명으로는 구독자 수보다 조회수가 오르는 속도와 화제성을 함께 보고 뽑으며 순위는 수시로 갱신된다. 다만 누가 언제 이 줄임말을 처음 썼는지 밝힌 출처는 없고, 유튜브가 한국에서 자리 잡는 동안 이용자들 사이에서 자연스럽게 굳은 것으로 보인다.', '{"de": "Eine Kurzform des koreanischen YouTube-Menüpunkts 인기 급상승 동영상 (Trends). Laut YouTube zählt weniger die Abonnentenzahl als das Tempo des Aufrufanstiegs und die Aufmerksamkeit; die Liste wird mehrmals täglich aktualisiert. Keine Quelle hält fest, wer sie zuerst abkürzte — sie hat sich offenbar unter Nutzern eingebürgert, als YouTube in Korea Fuß fasste.", "en": "A clipping of the YouTube Korean menu label 인기 급상승 동영상 (Trending). YouTube describes the ranking as based less on subscriber count than on how fast views are climbing and how much attention a clip is getting, refreshed repeatedly through the day. No source records who first shortened it; it seems to have settled among users as YouTube took hold in Korea.", "es": "Recorte del rótulo del menú coreano de YouTube 인기 급상승 동영상 (Tendencias). YouTube explica que el ranking depende menos del número de suscriptores que de la velocidad a la que suben las visitas y del revuelo, y se actualiza varias veces al día. Ninguna fuente registra quién lo abrevió primero; parece haber cuajado entre usuarios conforme YouTube se asentó en Corea.", "ja": "YouTube韓国語版のメニュー名「人気急上昇動画」の頭文字を取った略語。YouTubeの説明では登録者数より再生数の伸び方や注目度を見て選ばれ、順位は頻繁に更新される。ただし誰がいつ最初に略したかを示す出典はなく、韓国でYouTubeが定着する過程で自然に固まったとみられる。", "vi": "Rút gọn từ nhãn menu tiếng Hàn của YouTube 인기 급상승 동영상 (Thịnh hành). YouTube cho biết bảng này ít phụ thuộc số người đăng ký mà dựa vào tốc độ tăng lượt xem và mức được chú ý, được cập nhật liên tục trong ngày. Không nguồn nào ghi ai rút gọn đầu tiên; có vẻ nó tự định hình khi YouTube phổ biến ở Hàn."}'::jsonb, '''인급동 갔다 / 올랐다 / 떴다''처럼 동사를 붙여 쓴다. 크리에이터에게는 목표이자 자랑거리라 축하 댓글에 자주 나오고, 시청자끼리는 ''요즘 뭐가 핫한지''를 뜻하는 말로 쓴다. 사람에게 쓰면 어색하고, 오직 콘텐츠에만 붙는다.', '{"de": "Wird mit Verb gebraucht: 인급동 갔다 / 올랐다 (hat es in die Trends geschafft). Für Creator ist es Ziel und Prahlerei, taucht also in Glückwunschkommentaren auf; unter Zuschauern steht es für ''was gerade angesagt ist''. Es bezieht sich nur auf Inhalte, nie auf Personen.", "en": "Used with a verb: 인급동 갔다 / 올랐다 (made it to trending). For creators it is a goal and a brag, so it shows up in congratulation comments; among viewers it is shorthand for ''what''s hot right now''. It attaches only to content, never to a person.", "es": "Se usa con verbo: 인급동 갔다 / 올랐다 (llegó a tendencias). Para los creadores es meta y motivo de orgullo, así que aparece en comentarios de felicitación; entre espectadores equivale a ''lo que está de moda ahora''. Se aplica solo a contenidos, nunca a personas.", "ja": "「인급동 갔다/올랐다(急上昇に入った)」のように動詞と一緒に使う。クリエイターにとっては目標であり自慢なのでお祝いコメントによく出て、視聴者同士では「今何が熱いか」を指す語として使う。人には付けず、コンテンツ専用。", "vi": "Dùng kèm động từ: 인급동 갔다 / 올랐다 (lên thịnh hành). Với người sáng tạo đây là mục tiêu và niềm tự hào nên hay xuất hiện trong bình luận chúc mừng; giữa người xem thì là cách nói ''giờ cái gì đang hot''. Chỉ gắn cho nội dung, không dùng cho người."}'::jsonb, array['떡상','쇼츠','역주행'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Trending (YouTube''s trending videos)"}, {"lang": "🇯🇵 JA", "text": "急上昇(人気急上昇動画)"}, {"lang": "🇨🇳 ZH", "text": "热门飙升视频"}, {"lang": "🇻🇳 VI", "text": "Video thịnh hành (YouTube)"}, {"lang": "🇪🇸 ES", "text": "Tendencias de YouTube"}, {"lang": "🇩🇪 DE", "text": "YouTube-Trends"}]'::jsonb),
('480', '박제', 'Bak-je', 'reels', 'frequently-used', '남의 말·행동을 캡처해 영원히 남기기', '{"de": "Jemandes Worte per Screenshot für immer festhalten", "en": "Screenshotting someone''s words so they live online forever", "es": "Capturar las palabras de alguien para que queden para siempre", "ja": "他人の発言をキャプチャして永久に残すこと", "vi": "Chụp lại lời nói của ai đó để lưu vĩnh viễn"}'::jsonb, null, '[{"type": "명사·동사", "examples": [{"de": "Der Kommentar ist längst gescreenshottet. Löschen bringt nichts.", "es": "Ese comentario ya lo capturaron. Borrarlo no sirve de nada.", "ja": "あのコメントもう晒されてたよ。消しても無駄。", "vi": "Bình luận đó bị chụp lại rồi. Xoá cũng vô ích.", "eng": "That comment already got screenshotted. Deleting won''t help.", "kor": "그 댓글 벌써 박제당했더라. 지워도 소용없어."}, {"de": "Ein Video von mir aus der Schulzeit ist für immer archiviert — mir ist es bis heute peinlich.", "es": "Un vídeo mío del instituto quedó inmortalizado y todavía me da vergüenza ajena.", "ja": "高校のときの動画が晒されて、いまだに悶える。", "vi": "Cái video hồi cấp ba của mình bị lưu mãi, giờ nghĩ vẫn muốn độn thổ.", "eng": "A video of me from high school is archived forever and I still cringe about it.", "kor": "고등학교 때 영상 박제돼서 아직도 이불킥해."}], "definition": "인터넷에서 누군가의 말이나 행동을 캡처·녹화·저장해 지워도 사라지지 않는 기록으로 남기는 일. 나중에 증거로 들이밀거나 망신을 주려는 목적이 대부분이라 부정적인 말이다. 지운 글도 캡처는 남는다는 점이 핵심이어서, 자기 흑역사가 퍼졌을 때는 ''박제당했다''라고 한다. 표준국어대사전에 실린 ''박제''는 동물 표본을 뜻하고, 이 인터넷 뜻은 거기서 온 비유일 뿐 사전에는 없다.", "definition_i18n": {"de": "Etwas, das jemand online gesagt oder getan hat, per Screenshot, Aufnahme oder Archiv so festhalten, dass es jede Löschung überlebt. Meist geht es um Beweise oder Bloßstellung — der Witz ist ja, dass der Beitrag verschwinden kann, der Screenshot nicht. Trifft es einen selbst, sagt man 박제당했다 (ich wurde verewigt). Im Wörterbuch bedeutet 박제 ein ausgestopftes Tier; die Internetbedeutung ist nur eine Metapher davon und dort nicht verzeichnet.", "en": "Capturing, recording or archiving what someone said or did online so that it survives any deletion. The intent is usually to keep evidence or to humiliate, which makes it a negative word — the whole point is that the post can be erased but the screenshot cannot. When it happens to you, you say 박제당했다 (I got immortalised). The dictionary word 박제 means a taxidermy mount; this internet sense is a metaphor from it and is not in the dictionary.", "es": "Capturar, grabar o archivar lo que alguien dijo o hizo en internet para que sobreviva a cualquier borrado. Suele buscar guardar pruebas o humillar, así que es una palabra negativa: la gracia es que el mensaje se borra pero la captura no. Si te pasa a ti, dices 박제당했다 (me inmortalizaron). En el diccionario, 박제 significa animal disecado; este sentido de internet es una metáfora y no está recogido.", "ja": "ネット上の誰かの発言や行動をキャプチャ・録画・保存し、消しても残る記録にすること。証拠として突きつけたり恥をかかせたりする目的が大半なので否定的な語。投稿は消せてもスクショは消せない、というのが肝で、自分が被害者なら「박제당했다(晒された)」と言う。標準国語大辞典の「剝製」は動物標本の意味で、このネット用法はそこからの比喩にすぎず辞書には載っていない。", "vi": "Chụp màn hình, quay lại hay lưu trữ lời nói và hành vi của ai đó trên mạng để nó không mất đi dù bị xoá. Mục đích thường là giữ bằng chứng hoặc bêu riếu nên đây là từ mang nghĩa xấu — điểm mấu chốt là bài đăng xoá được còn ảnh chụp thì không. Khi bị như vậy, người ta nói 박제당했다 (bị lưu đời đời). Trong từ điển, 박제 nghĩa là tiêu bản thú nhồi bông; nghĩa mạng này chỉ là ẩn dụ và không có trong từ điển."}}]'::jsonb, '동물 가죽을 벗겨 살아 있을 때 모습 그대로 굳혀 두는 ''박제(剝製)''에서 온 비유다. 지운 글도 캡처로 남으면 그 순간의 모습이 그대로 굳는다는 점이 닮았다. 커뮤니티 게시판에서 ''이 발언 박제해 둔다''처럼 쓰이다가 SNS·숏폼으로 넘어왔는데, 처음 쓰인 사이트나 정확한 시점을 특정한 출처는 없다. 2010년대 후반에 널리 퍼졌다고 보는 설명이 있으나 한 곳에서만 확인된다.', '{"de": "Eine Metapher zu 박제 (剝製), der Taxidermie: ein Tier häuten und in seiner Lebendpose fixieren. Ein gelöschter Beitrag lebt im Screenshot genauso weiter — exakt eingefroren. Von Community-Foren, wo man schrieb ''diese Aussage halte ich fest'', wanderte es zu Social Media und Kurzvideos, doch keine Quelle nennt die erste Seite oder ein genaues Datum. Nur eine Darstellung datiert die Verbreitung auf die späten 2010er.", "en": "A metaphor from 박제 (剝製), taxidermy: skinning an animal and fixing it in the pose it had while alive. A deleted post lives on in a screenshot the same way — frozen exactly as it was. It spread from community boards, where people would write ''archiving this remark'', onto social media and short-form video, but no source identifies the first site or a precise date. One account dates its spread to the late 2010s, and only that one.", "es": "Metáfora de 박제 (剝製), la taxidermia: desollar un animal y fijarlo en la postura que tenía en vida. Una publicación borrada sobrevive igual en una captura, congelada tal cual. Pasó de los foros, donde se escribía ''me guardo esta frase'', a las redes y el vídeo corto, pero ninguna fuente señala el primer sitio ni una fecha exacta. Un relato sitúa su difusión a finales de los 2010, y solo ese.", "ja": "動物の皮を剥いで生前の姿のまま固定する「剝製」からの比喩。消した投稿もスクショに残ればその瞬間の姿のまま固まる、という点が似ている。コミュニティ掲示板で「この発言は박제しておく」のように使われ、SNSやショート動画へ広がったが、最初のサイトや正確な時期を特定した出典はない。2010年代後半に広まったとする説明が一つだけある。", "vi": "Ẩn dụ từ 박제 (剝製), nghề nhồi bông: lột da con vật rồi cố định ở dáng lúc còn sống. Bài viết bị xoá vẫn sống trong ảnh chụp y như vậy — đông cứng đúng khoảnh khắc đó. Từ các diễn đàn, nơi người ta viết ''lưu câu này lại'', nó lan sang mạng xã hội và video ngắn, nhưng không nguồn nào chỉ ra trang đầu tiên hay mốc thời gian chính xác. Chỉ một nguồn cho rằng nó lan rộng cuối thập niên 2010."}'::jsonb, '''박제하다 / 박제당하다 / 박제됐다'' 꼴로 쓴다. 동의 없이 남을 박제하는 것은 당사자에게 오래 남는 상처가 되고 도덕적으로도 문제라는 지적이 많아, 농담처럼 쓰더라도 실제로 할 때는 조심해야 한다. 반대로 팬덤에서는 최애의 귀여운 순간을 두고 ''이건 박제각''처럼 애정 섞어 쓰기도 한다.', '{"de": "Gebräuchlich als 박제하다 (festhalten), 박제당하다 (festgehalten werden), 박제됐다 (ist festgehalten). Ohne Einwilligung kann das dauerhaften Schaden anrichten und gilt vielen als unethisch — der Witz ist leicht, die Tat nicht. In Fandoms kippt es ins Liebevolle: ein süßer Moment des Bias ist 박제각, screenshotwürdig.", "en": "Used as 박제하다 (to archive), 박제당하다 (to get archived), 박제됐다 (it''s archived). Doing it to someone without consent can leave lasting harm and is widely criticised as unethical, so the joke is easy but the act is not. In fandoms, though, it flips affectionate: a cute moment from your bias is 박제각 — screenshot-worthy.", "es": "Se usa como 박제하다 (archivar), 박제당하다 (ser archivado), 박제됐다 (quedó archivado). Hacerlo sin consentimiento puede dejar un daño duradero y se critica como poco ético, así que la broma es fácil pero el acto no. En los fandoms, en cambio, es cariñoso: un momento tierno de tu bias es 박제각, digno de captura.", "ja": "「박제하다(晒す)/박제당하다(晒される)/박제됐다」の形で使う。同意なしに他人を晒す行為は当人に長く残る傷を与え、倫理的にも問題だという指摘が多いので、冗談で使うのは簡単でも実行は慎重に。一方ファンダムでは推しのかわいい瞬間に「これは박제각(保存案件)」と愛情込めて使う。", "vi": "Dùng ở dạng 박제하다 (lưu lại), 박제당하다 (bị lưu lại), 박제됐다 (đã bị lưu). Làm vậy với người khác mà không xin phép có thể để lại tổn thương lâu dài và bị chê là thiếu đạo đức, nên đùa thì dễ chứ làm thật thì phải cân nhắc. Ngược lại trong fandom nó mang nghĩa cưng: khoảnh khắc dễ thương của idol là 박제각, đáng chụp lại."}'::jsonb, array['짤','움짤','어그로'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "To immortalise / screenshot as permanent proof"}, {"lang": "🇯🇵 JA", "text": "晒す・魚拓を取る"}, {"lang": "🇨🇳 ZH", "text": "挂人、留证截图"}, {"lang": "🇻🇳 VI", "text": "Lưu ảnh chụp làm bằng chứng bêu"}, {"lang": "🇪🇸 ES", "text": "Inmortalizar con captura"}, {"lang": "🇩🇪 DE", "text": "Per Screenshot verewigen"}]'::jsonb),
('481', '장항준적 사고', 'Jang-hang-jun-jeok Sa-go', 'reels', null, '남 눈치 안 보고 내 행복부터 챙기는 초긍정 마이웨이', '{"de": "Unbekümmerter Optimismus — Blicke ignorieren, das eigene Glück zuerst", "en": "Unbothered optimism — ignore the judging eyes, put your own happiness first", "es": "Optimismo despreocupado: pasa de las miradas y prioriza tu felicidad", "ja": "他人の目を気にせず自分の幸せを優先する超ポジティブなマイウェイ", "vi": "Lạc quan kiểu bất cần: mặc kệ ánh nhìn, ưu tiên hạnh phúc của mình"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Abgelehnt — na und, ich fahr jetzt voll unbekümmert.", "es": "Me rechazaron, ¿y qué? Voy en modo despreocupado total.", "ja": "落ちたけど別にいいや、장항준的思考でいく。", "vi": "Trượt thì trượt, cứ theo kiểu bất cần mà sống.", "eng": "So I got rejected — whatever, I''m going full unbothered mode.", "kor": "떨어졌는데 뭐 어때, 장항준적 사고로 가는 거지."}, {"de": "Lern dir ein bisschen diese unbekümmerte Denke an — egal, was andere sagen.", "es": "Aprende un poco de ese pensamiento despreocupado; qué más da lo que digan.", "ja": "장항준的思考を少し学びなよ、他人が何と言おうと関係ない。", "vi": "Học chút lối nghĩ bất cần đi, người ta nói gì thì liên quan gì.", "eng": "Learn some of that unbothered thinking — who cares what people say.", "kor": "장항준적 사고 좀 배워라, 남들이 뭐라든 무슨 상관이야."}], "definition": "남의 평가나 사회가 정한 기준에 자기를 맞추지 않고, 어떤 상황에서도 자기 행복을 먼저 놓는 사고방식. 핵심은 ''자존심은 낮추되 자존감은 높인다''로, 안 되는 건 담백하게 인정하고 비판이 오면 주눅 들지 않고 받아치며 거절당한 일은 빨리 잊는다. 이미 자리 잡은 ''원영적 사고''와 같은 ''○○적 사고'' 틀이지만, 원영적 사고가 ''모든 일을 행운으로 해석하는'' 쪽이라면 이쪽은 ''애초에 신경을 안 쓰는'' 쪽에 가깝다.", "definition_i18n": {"de": "Eine Haltung, die sich nicht an fremdem Urteil oder gesellschaftlichen Maßstäben misst und das eigene Glück in jeder Lage voranstellt. Kern ist ''Stolz runter, Selbstwert rauf'': nüchtern zugeben, was nicht klappt, auf Kritik antworten statt einzuknicken, Absagen schnell vergessen. Dasselbe ○○적 사고-Muster wie das etablierte 원영적 사고 — nur deutet jenes alles als Glück um, während dieses sich schlicht nicht kümmert.", "en": "A mindset that refuses to measure itself against other people''s judgement or society''s standards and puts your own happiness first in any situation. The core is ''lower the pride, raise the self-worth'': admit plainly what isn''t working, answer criticism without shrinking, and forget rejection fast. It uses the same ○○적 사고 frame as the already-established 원영적 사고, but where that one reinterprets everything as luck, this one simply doesn''t care in the first place.", "es": "Una mentalidad que se niega a medirse por el juicio ajeno o los estándares sociales y pone tu felicidad por delante en cualquier situación. La clave es ''baja el orgullo, sube la autoestima'': admitir sin drama lo que no sale, responder a las críticas sin encogerse y olvidar rápido los rechazos. Usa el mismo molde ○○적 사고 que el ya asentado 원영적 사고, pero mientras aquel reinterpreta todo como suerte, este directamente no se preocupa.", "ja": "他人の評価や世間の基準に自分を合わせず、どんな状況でも自分の幸せを先に置く考え方。核心は「自尊心は下げ、自己肯定感は上げる」で、できないことはあっさり認め、批判が来ても萎縮せず返し、断られたことは早く忘れる。すでに定着した「원영적 사고」と同じ「○○的思考」の型だが、あちらが「すべてを幸運と解釈する」なら、こちらは「そもそも気にしない」に近い。", "vi": "Lối nghĩ không tự đo mình bằng đánh giá của người khác hay chuẩn mực xã hội, và đặt hạnh phúc bản thân lên trước trong mọi hoàn cảnh. Cốt lõi là ''hạ cái tôi, nâng lòng tự trọng'': thừa nhận nhẹ nhàng điều không ổn, bị chê thì đáp lại chứ không co rúm, bị từ chối thì quên nhanh. Nó dùng đúng khuôn ○○적 사고 như 원영적 사고 đã phổ biến, nhưng nếu kia diễn giải mọi thứ thành may mắn thì cái này đơn giản là không bận tâm."}}]'::jsonb, '영화감독 장항준이 여러 인터뷰와 방송에서 보여 온 태도를 이름 삼아 만든 말로, 2026년 초부터 SNS와 숏폼에서 퍼졌다. 인물 이름에 ''-적 사고''를 붙이는 틀은 2024년 유행한 ''원영적 사고''가 만든 것이고, 이 말은 그 틀을 그대로 빌려 온 파생어다. 다만 어느 인터뷰의 어떤 발언이 결정적 계기였는지 특정한 출처는 없다.', '{"de": "Geprägt nach der Haltung, die Regisseur Jang Hang-jun in diversen Interviews und Sendungen zeigt; verbreitet in Social Media und Kurzvideos ab Anfang 2026. Das Muster, einem Personennamen -적 사고 (''Denke à la …'') anzuhängen, stammt von 원영적 사고, das 2024 groß wurde; dies ist eine direkte Übernahme. Keine Quelle benennt das auslösende Interview oder Zitat.", "en": "Coined from the attitude film director Jang Hang-jun has shown across interviews and broadcasts, it spread on social media and short-form video from early 2026. The pattern of attaching -적 사고 (-ish thinking) to a person''s name was created by 원영적 사고, which took off in 2024; this is a direct borrowing of that frame. No source pins down which interview or remark set it off.", "es": "Acuñado a partir de la actitud que el director de cine Jang Hang-jun ha mostrado en entrevistas y programas, se difundió en redes y vídeo corto desde principios de 2026. El patrón de añadir -적 사고 (''pensamiento a lo…'') a un nombre propio lo creó 원영적 사고, que estalló en 2024; este es un préstamo directo de ese molde. Ninguna fuente concreta qué entrevista o frase lo detonó.", "ja": "映画監督チャン・ハンジュンが数々のインタビューや番組で見せてきた態度を名前にした語で、2026年初めからSNSやショート動画で広がった。人名に「〜的思考」を付ける型は2024年に流行した「원영적 사고」が作ったもので、これはその型をそのまま借りた派生語。ただしどのインタビューのどの発言が決定打だったかを示す出典はない。", "vi": "Đặt theo thái độ mà đạo diễn Jang Hang-jun thể hiện qua nhiều cuộc phỏng vấn và chương trình, cụm này lan trên mạng xã hội và video ngắn từ đầu 2026. Khuôn gắn -적 사고 (''lối nghĩ kiểu…'') vào tên người là do 원영적 사고 tạo ra hồi 2024; đây là bản vay mượn trực tiếp khuôn đó. Không nguồn nào xác định phỏng vấn hay câu nói nào châm ngòi."}'::jsonb, '''장항준적 사고로 살다 / 장항준적 사고 좀 배워라''처럼 태도를 가리키는 말로 쓴다. 떨어졌거나 까였을 때 스스로를 다독이는 자기 위로에 가장 많이 쓰이고, 남에게 권할 때도 나쁜 뜻이 아니다. 다만 실존 인물 이름이 들어간 말이라 그 사람을 모르는 자리에서는 설명이 필요하고, 진지한 사과나 반성이 필요한 자리에서 꺼내면 무책임하게 들린다.', '{"de": "Dient als Name für eine Haltung: danach leben, oder ''lern dir was davon ab''. Meist ist es Selbsttrost nach Absage oder Rückschlag, und es jemandem zu empfehlen ist keine Beleidigung. Da ein realer Name darin steckt, braucht es eine Erklärung für Unwissende — und wo eine echte Entschuldigung fällig ist, klingt es verantwortungslos.", "en": "Used as a name for an attitude: 장항준적 사고로 살다 (live by it), 장항준적 사고 좀 배워라 (learn some of it). Most often it is self-comfort after a rejection or a knock, and recommending it to someone is not an insult. Because it contains a real person''s name it needs explaining to anyone who doesn''t know him — and pulling it out where a genuine apology is due sounds irresponsible.", "es": "Se usa como nombre de una actitud: vivir con ese pensamiento, o ''aprende un poco de él''. Sobre todo sirve de autoconsuelo tras un rechazo o un golpe, y recomendarlo no es un insulto. Como lleva el nombre de una persona real, hay que explicarlo a quien no lo conozca, y sacarlo donde toca una disculpa sincera suena irresponsable.", "ja": "「장항준적 사고로 살다(その考え方で生きる)」「장항준적 사고 좀 배워라(少し学べ)」のように態度を指す語として使う。落ちたり断られたりしたときの自己慰めが最も多く、人に勧めても悪い意味ではない。ただし実在の人物名が入っているため知らない相手には説明が要り、本気の謝罪や反省が必要な場面で持ち出すと無責任に聞こえる。", "vi": "Dùng như tên gọi của một thái độ: sống theo lối nghĩ đó, hoặc ''học chút đi''. Thường nhất là tự an ủi sau khi bị từ chối hay vấp ngã, và khuyên người khác cũng không phải lời chê. Vì có tên một người thật nên phải giải thích với ai chưa biết ông ấy, còn đem ra dùng lúc cần xin lỗi thật lòng thì nghe vô trách nhiệm."}'::jsonb, array['원영적 사고','럭키비키','오히려 좋아'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Unbothered, my-own-happiness-first thinking"}, {"lang": "🇯🇵 JA", "text": "チャン・ハンジュン的思考(超ポジティブなマイウェイ)"}, {"lang": "🇨🇳 ZH", "text": "张恒俊式思维(不在乎他人眼光)"}, {"lang": "🇻🇳 VI", "text": "Lối nghĩ kiểu Jang Hang-jun (bất cần, tự ưu tiên mình)"}, {"lang": "🇪🇸 ES", "text": "Pensamiento a lo Jang Hang-jun (despreocupado)"}, {"lang": "🇩🇪 DE", "text": "Denke à la Jang Hang-jun (unbekümmert)"}]'::jsonb);

-- After apply: select count(*) from public.words; → 398
